# Check neighbors for the 3 cells that stayed 3 vs changed
import numpy as np

def get_neighbors(grid, r, c):
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                neighbors.append((grid[nr][nc], (nr, nc)))
    return neighbors

print("Neighbors of cells that stayed 3:")
stayed_3 = [(0,8), (0,16), (3,7)]
for (r,c) in stayed_3:
    nums = [n[0] for n in get_neighbors(input_grid, r, c)]
    print(f"  {input_grid[r][c]} at ({r},{c}): neighbors = {nums}")

print("\nNeighbors of some cells that changed to 8:")
changed_cells = [(0,0), (0,4), (1,9)]
for (r,c) in changed_cells:
    nums = [n[0] for n in get_neighbors(input_grid, r, c)]
    print(f"  {input_grid[r][c]} at ({r},{c}): neighbors = {nums}")

# Check if the stayed-3 cells are part of the main connected component
def find_connected_comp(grid, start_r, start_c, target_val):
    visited = set()
    queue = [(start_r, start_c)]
    comp_cells = set()

    while queue:
        r, c = queue.pop(0)
        if (r, c) in visited:
            continue
        if grid[r][c] != target_val:
            continue
        visited.add((r, c))
        comp_cells.add((r, c))

        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if (nr, nc) not in visited and grid[nr][nc] == target_val:
                        queue.append((nr, nc))

    return comp_cells

# Get the main component (starting from first 3)
main_component = find_connected_comp(input_grid, 0, 0, 3)
print(f"Size of main component: {len(main_component)}")

# Check if stayed-3 cells are in main component
for cell in stayed_3:
    in_main = cell in main_component
    print(f"  {cell} in main component: {in_main}")

# Let me also check if maybe it's about being an "extremal" cell
# in each row - like leftmost or rightmost 3 in a row
print("\nChecking extremal cells in each row:")
for r in range(4):
    row_3s = [(c, input_grid[r][c]) for c in range(18) if input_grid[r][c] == 3]
    if row_3s:
        leftmost = row_3s[0][0]
        rightmost = row_3s[-1][0]
        print(f"  Row {r}: 3s at columns {row_3s}, leftmost={leftmost}, rightmost={rightmost}")
        # Check output for these positions
        for c in [leftmost, rightmost]:
            out_val = output_grid[r][c]
            in_stayed = c in [s[0] for s in stayed_3] if r == output_grid[r][c] == 3 else False

# Find all connected components of 3s (using 8-connectivity)
def find_all_connected_components(grid, target_val):
    visited = set()
    components = []

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r, c) in visited or grid[r][c] != target_val:
                continue

            # Start a new BFS
            comp = []
            queue = [(r, c)]
            while queue:
                cr, cc = queue.pop(0)
                if (cr, cc) in visited:
                    continue
                visited.add((cr, cc))
                comp.append((cr, cc))

                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == target_val and (nr, nc) not in visited:
                                queue.append((nr, nc))
            components.append(comp)

    return components

components = find_all_connected_components(input_grid, 3)
print(f"Number of connected components of 3s: {len(components)}")
for i, comp in enumerate(components):
    print(f"  Component {i}: size={len(comp)}, cells={sorted(comp)}")

# Let me create a more visual representation of the components
# I'll mark 1 for component 0, 2 for component 1, 0 for background

component_grid = [[0]*18 for _ in range(4)]
for cell in components[0]:
    component_grid[cell[0]][cell[1]] = 1
for cell in components[1]:
    component_grid[cell[0]][cell[1]] = 2

print("Component grid (1=comp 0, 2=comp 1):")
for row in component_grid:
    print(" ".join([str(c) for c in row]))

print("\nOutput analysis (3 stays, 8 changes):")
print("S = stay, C = change to 8, 0 = background")
for r in range(4):
    row_str = ""
    for c in range(18):
        if input_grid[r][c] == 0:
            row_str += "0 "
        else:
            if output_grid[r][c] == 3:
                row_str += "S "
            else:
                row_str += "C "
    print(row_str)

# Count same-component neighbors for each cell
for i, comp in enumerate(components):
    print(f"\nComponent {i}:")
    for (r, c) in sorted(comp):
        # Count neighbors within same component
        same_neighbors = 0
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(input_grid) and 0 <= nc < len(input_grid[0]):
                    if (nr, nc) in comp:
                        same_neighbors += 1
        # Check if this cell stayed 3 or changed
        output_val = output_grid[r][c]
        stayed = output_val == 3
        color_code = "S" if stayed else "C" if output_val == 8 else "?"
        print(f"  ({r}, {c}): same-neighs={same_neighbors}, output={color_code}")

